import React, { PropsWithChildren } from "react";
import { Box, Flex, Skeleton, Text, TooltipComponent } from "../../atoms";
import { buttonReset, styled } from "../../../stitches.config";
import { LVectorIcon } from "./icons/LVectorIcon";
import { SortIcon } from "./icons/SortIcon";
import { HelpIcon } from "../../icons";

type ExpandedTableRootProps = {
  children: React.ReactNode;
};

const ExpandedTableRoot: React.FC<ExpandedTableRootProps> = ({ children }) => (
  <Box
    css={{
      display: "flex",
      gap: "$sm",
      height: "100%",
      maxHeight: "312px",
      position: "relative",
      width: "100%",
      boxSizing: "border-box",
      border: "none !important",
      boxShadow: "none !important",
      overflowY: "auto",
      overflowX: "auto",
      paddingBottom: "22px",
      scrollbarWidth: "none",
      "& th": {
        border: "none !important",
      },
      "& tr": {
        border: "none !important",
      },
      "& td": {
        border: "none !important",
      },
    }}
  >
    <Box
      css={{
        marginLeft: "$xl",
      }}
    >
      <LVectorIcon />
    </Box>
    <table
      style={{
        marginTop: "$xl",
        width: "100%",
        borderCollapse: "collapse",
        boxSizing: "border-box",
      }}
    >
      {children}
    </table>
  </Box>
);

const ExpandedTableHead: React.FC<PropsWithChildren> = ({ children }) => (
  <thead>
    <tr>{children}</tr>
  </thead>
);

export const ExpandedTableBody = styled("tbody", {});

export const ExpandedTableRow = styled("tr", {});

export const ExpandedTableCell = styled("td", {
  paddingRight: "$xl",
  paddingLeft: "$xs",
});

const ExpandedTableHeader = styled("th", {
  color: "$grayMedium",
  fontSize: 16,
  fontWeight: "bold",
  lineHeight: "24px",
  textAlign: "left",
  paddingBottom: 8,
  variants: {
    isSortable: {
      true: {
        cursor: "pointer",
        paddingLeft: "$2",
      },
      false: {
        cursor: "default",
      },
    },
    isSortActive: {
      true: {
        color: "$light",
        "& svg": {
          color: "$light",
        },
      },
      false: {
        "& svg": {
          "@sm": {
            color: "$body", // Default color for mobile
          },
          "@bp2": {
            color: "transparent", // Transparent for larger screens
          },
        },
      },
    },
    uppercase: {
      true: {
        textTransform: "uppercase",
        fontWeight: "$medium",
      },
    },
  },
  "&:hover svg": {
    color: "$light",
  },
});

type ExpandedTableHeaderCellProps = {
  isSortable?: boolean;
  isSortActive?: boolean;
  sortDirection?: "desc" | "asc";
  tooltipContent?: string;
  onClick?: () => void;
  variant?: "uppercase";
};

const ExpandedTableHeaderCell: React.FC<
  PropsWithChildren<ExpandedTableHeaderCellProps>
> = ({
  isSortable = false,
  isSortActive = false,
  sortDirection,
  tooltipContent = null,
  onClick,
  variant,
  children,
}) => (
  <ExpandedTableHeader
    isSortActive={isSortActive}
    isSortable={isSortable}
    onClick={isSortable ? undefined : onClick}
    aria-sort={
      !isSortable
        ? undefined
        : !isSortActive
          ? "none"
          : sortDirection === "asc"
            ? "ascending"
            : "descending"
    }
    uppercase={variant === "uppercase"}
  >
    <Flex css={{ gap: "$xxxs", alignItems: "center" }}>
      {isSortable ? (
        <Flex
          as="button"
          type="button"
          onClick={onClick}
          css={{
            ...buttonReset,
            width: "auto",
            gap: "$xxxs",
            alignItems: "center",
          }}
        >
          <SortIcon direction={isSortActive ? sortDirection : "desc"} />
          {children}
        </Flex>
      ) : (
        children
      )}
      {tooltipContent && (
        <TooltipComponent content={tooltipContent}>
          <Box css={{ display: "flex" }}>
            <HelpIcon />
          </Box>
        </TooltipComponent>
      )}
    </Flex>
  </ExpandedTableHeader>
);

const ExpandedTableLoadingContent: React.FC<{
  columnsCount?: number;
  rowsCount?: number;
}> = ({ columnsCount = 4, rowsCount = 5 }) => {
  return (
    <>
      {Array.from({ length: rowsCount }).map((_, rowIndex) => (
        <ExpandedTableRow key={rowIndex}>
          {Array.from({ length: columnsCount }).map((_, colIndex) => (
            <ExpandedTableCell key={colIndex}>
              <Skeleton variant="title" />
            </ExpandedTableCell>
          ))}
        </ExpandedTableRow>
      ))}
    </>
  );
};

const ExpandedTableNoResultsContent: React.FC<{ columnsCount?: number }> = ({
  columnsCount = 4,
}) => {
  return (
    <ExpandedTableRow>
      <ExpandedTableCell colSpan={columnsCount} style={{ textAlign: "center" }}>
        <Box css={{ paddingTop: "$lg", paddingBottom: "$lg" }}>
          <Text variant="h5">No matching results</Text>
        </Box>
      </ExpandedTableCell>
    </ExpandedTableRow>
  );
};

export const ExpandedTable = {
  Root: ExpandedTableRoot,
  Head: ExpandedTableHead,
  Body: ExpandedTableBody,
  Row: ExpandedTableRow,
  Cell: ExpandedTableCell,
  Header: ExpandedTableHeaderCell,
  Loading: ExpandedTableLoadingContent,
  NoResults: ExpandedTableNoResultsContent,
};
