const StyledTable = styled("table", {
  width: "100%",
  borderCollapse: "collapse",
  minWidth: "max-content",
  tableLayout: "auto",
  variants: {
    variant: {
      border: {
        tableLayout: "auto",
        boxShadow: "0 0 0 2px var(--colors-bg04)",
        borderStyle: "hidden",
        borderRadius: "2px",
        borderCollapse: "collapse",
        "& thead": { backgroundColor: "transparent" },
        "& tr": {
          border: "2px solid var(--colors-bg04)",
        },
        "& .table-v2-td, & .table-v2-th": {
          border: "2px solid var(--colors-bg04)",
          "&:first-child": {
            backgroundColor: "$bg02",
            position: "relative",
          },
        },
      },
    },
    layout: {
      // Columns size to their content; the table can grow past its container
      // and scroll.
      auto: {},
      // Column widths come from the header cells (e.g. `css={{ width: "40%" }}`
      // on TableV3.Header) and the table fills its container. Cells that do
      // not fit are cut with an ellipsis instead of spilling over.
      fixed: {
        tableLayout: "fixed",
        width: "100%",
        minWidth: 0,
        "& .table-v2-td, & .table-v2-th": {
          overflow: "hidden",
          textOverflow: "ellipsis",
        },
      },
    },
  },
  compoundVariants: [
    {
      variant: "border",
      layout: "fixed",
      css: { tableLayout: "fixed" },
    },
  ],
  defaultVariants: {
    layout: "auto",
  },
});

