type TableHeaderProps = {
  isSortable?: boolean;
  isSortActive?: boolean;
  sortDirection?: "desc" | "asc";
  tooltipContent?: string;
  onClick?: () => void;
  variant?: "uppercase";
  css?: CSS;
};

const TableHeader: React.FC<PropsWithChildren<TableHeaderProps>> = ({
  isSortable = false,
  isSortActive = false,
  sortDirection,
  tooltipContent = null,
  onClick,
  variant,
  css,
  children,
}) => (
  <Header
    className="table-v2-th"
    isSortActive={isSortActive}
    isSortable={isSortable}
    onClick={isSortable ? undefined : onClick}
    aria-sort={
      !isSortable
        ? undefined
        : !isSortActive
          ? "none"
          : sortDirection === "asc"
            ? "ascending"
            : "descending"
    }
    uppercase={variant === "uppercase"}
    css={css}
  >
    <Flex css={{ gap: "$xxxs", alignItems: "center" }}>
      {isSortable ? (
        <Flex
          as="button"
          type="button"
          onClick={onClick}
          css={{
            ...buttonReset,
            width: "auto",
            gap: "$xxxs",
            alignItems: "center",
          }}
        >
          <SortIcon direction={isSortActive ? sortDirection : "desc"} />
          {children}
        </Flex>
      ) : (
        children
      )}
      {tooltipContent && (
        <TooltipComponent content={tooltipContent}>
          <Box css={{ display: "flex" }}>
            <HelpIcon />
          </Box>
        </TooltipComponent>
      )}
    </Flex>
  </Header>
);

