type TablePaginationWrapperProps = {
  currentPage: number;
  totalCount: number;
  dataLength: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  /** Rows per page; defaults to 10. */
  pageSize?: number;
  /** With onPageSizeChange: show a rows-per-page picker, e.g. [10, 20, 50, 100]. */
  pageSizeOptions?: number[];
  onPageSizeChange?: (pageSize: number) => void;
};

const PageSizeSelect = styled("select", {
  backgroundColor: "$bg03",
  color: "$textLight",
  border: "1px solid $bg05",
  borderRadius: "$2",
  fontSize: "$2",
  padding: "2px $xxs",
  cursor: "pointer",
  "&:focus-visible": { outline: "2px solid $obolGreen", outlineOffset: "2px" },
});

const TablePaginationWrapper: React.FC<
  PropsWithChildren<TablePaginationWrapperProps>
> = ({
  currentPage,
  totalCount,
  dataLength,
  totalPages,
  onPageChange,
  pageSize,
  pageSizeOptions,
  onPageSizeChange,
  children,
}) => {
  return (
    <Flex css={{ flexDirection: "column", marginTop: "$2xl" }}>
      {children}
      <Flex
        css={{
          justifyContent: "space-between",
          marginTop: "$sm",
          alignItems: "center",
          gap: "$sm",
          flexWrap: "wrap",
        }}
      >
        {pageSizeOptions?.length && onPageSizeChange ? (
          // "Showing [20 ▾] of 89": the page size is the picker.
          <Flex css={{ alignItems: "center", gap: "$xxs", width: "auto" }}>
            <Text css={{ fontSize: "$2" }} color="body">
              Showing
            </Text>
            <PageSizeSelect
              aria-label="Rows per page"
              value={pageSize ?? pageSizeOptions[0]}
              onChange={(event) => onPageSizeChange(Number(event.target.value))}
            >
              {pageSizeOptions.map((option) => (
                <option key={option} value={option}>
                  {option}
                </option>
              ))}
            </PageSizeSelect>
            <Text css={{ fontSize: "$2" }} color="body">
              of {totalCount}
            </Text>
          </Flex>
        ) : (
          <PaginatorSummary
            currentPage={currentPage}
            totalCount={totalCount}
            dataLength={dataLength}
            pageSize={pageSize}
          />
        )}

        <Pagination
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={onPageChange}
        />
      </Flex>
    </Flex>
  );
};

type TableRootProps = {
  css?: CSS;
  children: ReactNode;
  variant?: "border";
  /**
   * `"auto"` (default) sizes columns to their content. `"fixed"` takes column
   * widths from the header cells and makes the table fill its container.
   */
  layout?: "auto" | "fixed";
};

const TableRoot: React.FC<TableRootProps> = ({
  children,
  css,
  variant,
  layout = "auto",
}) => {
  return (
    <TableContainer variant={variant} css={css}>
      <StyledTable variant={variant} layout={layout}>
        {children}
      </StyledTable>
    </TableContainer>
  );
};

