import React from "react";
import { Flex, Text } from "../../atoms";

const DEFAULT_PAGE_SIZE = 10;

type PaginatorSummaryProps = {
  dataLength: number;
  currentPage: number;
  totalCount: number;
  /** Rows per page; defaults to 10. */
  pageSize?: number;
};

export const PaginatorSummary: React.FC<PaginatorSummaryProps> = ({
  currentPage,
  totalCount,
  dataLength,
  pageSize = DEFAULT_PAGE_SIZE,
}) => (
  <Flex
    css={{
      gap: "$xxs",
      width: "auto",
    }}
  >
    <Text css={{ fontSize: "$2" }} color="body">
      Showing:
    </Text>
    <Text css={{ fontSize: "$2" }}>
      {(currentPage - 1) * pageSize + dataLength}
    </Text>
    <Text css={{ fontSize: "$2" }} color="body">
      of {totalCount}
    </Text>
  </Flex>
);
